import { useContext, useEffect, useState } from 'react';

import PohButton, { ButtonVariant, ButtonSize } from '@ui-kit/Button';

import SocialProviderCard from './SocialProviderCard';
import socialVisualizeResource from './socialVisualizeResource';
import style from './style.module.less';
import { AuthContext, IAuthContext } from '../../../../contexts/AuthContext';
import { getProvidersList } from '../../@services/auth.services';
import { IAuthProviderDTO } from '../../@types/auth.types';

const SocialAuth = ({ onEnd }: { onEnd: IAuthContext['onLogin'] }) => {
  const authContext = useContext(AuthContext);
  const [list, setList] = useState<IAuthProviderDTO[] | null>(null);
  const [isShowMore, setIsShowMore] = useState(false);

  useEffect(() => {
    async function fetch() {
      const providersList = await getProvidersList();
      setList(providersList);
    }
    fetch();
  }, []);
  if (list == null) {
    return 'Loading...';
  }

  const providers = list.map((x) => ({ ...x, ...socialVisualizeResource[x.id] }));

  return (
    <div className={style.socList}>
      {providers.slice(0, 2).map((x) => (
        <SocialProviderCard
          key={x.id}
          id={x.id}
          name={x.name}
          link={x.url}
          color={x.bg}
          iconComponent={x.iconComponent}
          onLogin={authContext.onLogin}
          afterLogin={onEnd}
        />
      ))}
      {!isShowMore && (
        <PohButton
          className="w-100 d-block qa-socialAuthMore"
          size={ButtonSize.Small}
          variant={ButtonVariant.Light}
          onClick={() => setIsShowMore(true)}
        >
          <small>войти через другую соц.сеть</small>
        </PohButton>
      )}
      {isShowMore &&
        providers
          .slice(2)
          .map((x) => (
            <SocialProviderCard
              key={x.id}
              id={x.id}
              name={x.name}
              link={x.url}
              color={x.bg}
              iconComponent={x.iconComponent}
              onLogin={authContext.onLogin}
              afterLogin={onEnd}
            />
          ))}
    </div>
  );
};

export default SocialAuth;
