import React from 'react';

import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohLoader from '@ui-kit/Loader';

import { getExternalApp } from '../../@services/auth.services';
import { IExternalSystem } from '../../@types/auth.types';

interface IExternalAppProps {
  clientId: string;
  onData: (d: IExternalSystem) => void;
}

const ExternalApp = ({ clientId, onData }: IExternalAppProps) => {
  const [data, setData] = React.useState<IExternalSystem | null>(null);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const d = await getExternalApp(clientId);
        setData(d);
        onData(d);
      } catch (e) {
        setErr(e as Error);
      }
    };

    fetchData();
  }, [clientId]);

  if (!data) {
    return <PohLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  return (
    <div className="text-start mb-4 p-2 bg-light" style={{ borderRadius: 4 }}>
      <div className="d-flex mb-3">
        <PohAva width={58} src={data.img_url} />
        <div className="ms-3">
          <div className="text-danger">
            <small className="text-info">Вход через аккаунт походника в приложение:</small>
            <br />
            <b className="text-danger">{data.name}</b>
          </div>
          <details>
            Сайт:{' '}
            <a target="_blank" href={`//${data.domain}`} rel="noreferrer">
              {data.domain}
            </a>
            <br />
            <em>{data.description}</em>
            <hr />
            Источник: {document.referrer}
            <br />
          </details>
        </div>
      </div>
      <div className="border border-warning p-1 text-warning text-center">
        <small>
          <b>Не</b> продолжайте вход
          <br />
          если вы не доверяете этому приложению!
        </small>
      </div>
    </div>
  );
};

export default ExternalApp;
